<h1>المنتجات</h1><details class="card card-body mb-4" open><summary class="fw-bold mb-3">إضافة / تعديل منتج</summary><form method="post" enctype="multipart/form-data" action="<?= url('/admin/products/save') ?>"><?= csrf_field() ?><div class="row g-2"><div class="col-md-3"><select name="category_id" class="form-select"><?php foreach($categories as $c): ?><option value="<?= $c['id'] ?>"><?= e($c['name_ar']) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><input name="name_ar" required class="form-control" placeholder="اسم المنتج"></div><div class="col-md-2"><input name="slug" class="form-control" placeholder="slug"></div><div class="col-md-2"><input name="base_price" type="number" step=".01" class="form-control" placeholder="السعر"></div><div class="col-md-2"><input name="stock" type="number" class="form-control" placeholder="المخزون"></div><div class="col-12"><textarea name="description_ar" class="form-control" placeholder="الوصف"></textarea></div><div class="col-md-2"><input name="price_per_kg" type="number" step=".01" class="form-control" placeholder="سعر الكجم"></div><div class="col-md-3"><input name="weight_options_grams" class="form-control" value="250,500,750,1000"></div><div class="col-md-2"><input name="unit_label_ar" class="form-control" placeholder="الوحدة"></div><div class="col-md-2"><input name="sort_order" type="number" class="form-control" value="0"></div><div class="col-md-3"><input type="file" name="image" class="form-control"></div><div class="col-12"><label><input type="checkbox" name="is_weight_based"> يباع بالوزن</label> <label><input type="checkbox" name="is_active" checked> نشط</label></div><h6>البدائل (اختياري)</h6><div id="variants"><div class="row g-2 variant-row mb-2"><div class="col"><input name="variant_name[]" class="form-control" placeholder="اسم البديل"></div><div class="col"><input name="variant_price[]" type="number" step=".01" class="form-control" placeholder="السعر"></div><div class="col"><input name="variant_stock[]" type="number" class="form-control" placeholder="المخزون"></div><div class="col-auto"><button type="button" data-add-variant class="btn btn-outline-secondary">+</button></div></div></div><div class="col-12"><button class="btn btn-success">حفظ المنتج</button></div></div></form></details><table class="table bg-white"><tr><th>المنتج</th><th>القسم</th><th>السعر</th><th>المخزون</th><th></th></tr><?php foreach($products as $p): ?><tr><td><?= e($p['name_ar']) ?></td><td><?= e($p['category_name']) ?></td><td><?= e($productModel->displayPrice($p,$productModel->variants($p['id'],true))) ?></td><td><?= (int)$p['stock'] ?></td><td><form method="post" action="<?= url('/admin/products/delete') ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $p['id'] ?>"><button class="btn btn-sm btn-danger">حذف</button></form></td></tr><?php endforeach; ?></table>
